USE exocube_db;

-- 1. Crear la tabla de testimonios y valoraciones de la tienda si no existe
CREATE TABLE IF NOT EXISTS testimonios (
    id_testimonio INT AUTO_INCREMENT,
    nombre_cliente VARCHAR(100) NOT NULL,
    comentario TEXT NOT NULL,
    calificacion INT NOT NULL DEFAULT 5, -- Rango del 1 al 5 (Estrellas)
    fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id_testimonio)
) ENGINE=InnoDB;

